window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[139]={"id":"139","numero":139,"titre":"Item 139 — Soins palliatifs : repères cliniques & organisation","objectifs":[{"id":"139-1","rang":"A","rubrique":"Définition","titre":"Connaître les principes fondamentaux des soins palliatifs","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">soins palliatifs</span> sont des <span class=\"kw-ttt\">soins actifs et continus</span> assurant une <span class=\"kw-def\">prise en charge globale</span> du patient, dans le but d'<span class=\"kw-clinique\">améliorer la qualité de vie</span> du <span class=\"kw-clinique\">patient</span> et de ses <span class=\"kw-clinique\">proches</span>.</p>\n    <p>Quatre repères fondamentaux délimitent leur champ :</p>\n    <table class=\"descriptif-table\">\n      <thead><tr><th>Question</th><th>Repère fondamental</th></tr></thead>\n      <tbody>\n        <tr><td>Pour qui ?</td><td>Le <span class=\"kw-clinique\">patient</span> <strong>et</strong> ses <span class=\"kw-clinique\">proches</span></td></tr>\n        <tr><td>Quand ?</td><td>Dès une <span class=\"kw-alerte\">maladie grave potentiellement mortelle</span> — à débuter <span class=\"kw-chiffre\">le plus tôt possible</span></td></tr>\n        <tr><td>Par qui &amp; où ?</td><td><strong>Tout professionnel de santé</strong>, <span class=\"kw-chiffre\">quel que soit le lieu</span> où se trouve le patient</td></tr>\n        <tr><td>Quels buts ?</td><td><span class=\"kw-ttt\">Soins actifs et continus</span>, prise en charge globale pour améliorer la <span class=\"kw-clinique\">qualité de vie</span></td></tr>\n      </tbody>\n    </table>\n    <p>Une <span class=\"kw-def\">situation médicale palliative</span> se définit par le <span class=\"kw-alerte\">caractère non guérissable</span> d'une <span class=\"kw-clinique\">maladie chronique grave, évolutive et potentiellement létale</span>.</p>\n    <p>La maladie grave traverse plusieurs <span class=\"kw-def\">phases</span> :</p>\n    <table class=\"descriptif-table\">\n      <thead><tr><th>Phase</th><th>Caractéristiques</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-def\">Phase curative</span></td><td>Objectif médical = la <span class=\"kw-clinique\">guérison</span> ; prise en charge globale avec <span class=\"kw-ttt\">soins de support</span> pluridisciplinaires</td></tr>\n        <tr><td><span class=\"kw-def\">Phase palliative initiale</span></td><td><span class=\"kw-clinique\">Les</span> traitements spécifiques visent à <span class=\"kw-clinique\">freiner l'évolution</span> de la maladie ; <strong>soins palliatifs précoces</strong> = délivrés <span class=\"kw-chiffre\">en même temps</span> que ces traitements</td></tr>\n        <tr><td><span class=\"kw-def\">Phase palliative terminale</span></td><td><span class=\"kw-alerte\">Déclin fonctionnel et dégradation clinique irréversibles</span> ; soins palliatifs exclusifs après l'arrêt des traitements spécifiques</td></tr>\n        <tr><td><span class=\"kw-def\">Phase agonique</span></td><td><span class=\"kw-alerte\">Décès imminent</span> ; <span class=\"kw-alerte\">défaillance</span> multiviscérale évolutive</td></tr>\n      </tbody>\n    </table>\n    <div class=\"obj-callout info\"><strong>Cadre légal.</strong> La <span class=\"kw-def\">loi n° 99-477 du 9 juin 1999</span> garantit le <span class=\"kw-ttt\">droit d'accès aux soins palliatifs</span> à toute personne dont l'état le requiert.</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 140 — Soins palliatifs 2 - accompagnement de la personne et de son entourage · 141 — Soins palliatifs 3 - sédation - fin de vie</em></p>","frequence":0},{"id":"139-2","rang":"A","rubrique":"Définition","titre":"Connaître l’organisation des soins palliatifs en France","contenu":"<p>L'offre de soins palliatifs en France est <span class=\"kw-def\">graduée</span> selon la <span class=\"kw-clinique\">complexité</span> de la situation et adaptée aux besoins du patient et de ses proches. Elle repose sur des structures dédiées, à l'hôpital comme en ambulatoire.</p>\n    <table class=\"descriptif-table\">\n      <thead><tr><th>Structure</th><th>Définition &amp; missions</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-def\">LISP</span> — Lits identifiés de soins palliatifs</td><td>Lits dédiés au sein d'un <span class=\"kw-clinique\">service hospitalier</span> non exclusivement consacré aux soins palliatifs, mais confronté à des fins de vie ou des décès fréquents ; équipes formées aux <span class=\"kw-clinique\">situations non complexes</span> ; missions de soins et d'accompagnement des proches</td></tr>\n        <tr><td><span class=\"kw-def\">EMSP</span> — Équipe mobile de soins palliatifs (intra-hospitalière)</td><td>Équipe <span class=\"kw-clinique\">multidisciplinaire</span> rattachée à un établissement, qui se déplace au lit du malade et auprès des soignants ; <strong>triple mission :</strong> soins, formation, recherche ; ne pratique pas directement d'actes de soins</td></tr>\n        <tr><td><span class=\"kw-def\">EMSP extra-hospitalière / Réseau</span></td><td>Structures intervenant au <span class=\"kw-clinique\">domicile</span> ou en établissement médico-social (EHPAD) ; facilitent l'accès aux soins palliatifs hors de l'hôpital ; le « réseau » désigne plutôt la <span class=\"kw-clinique\">coordination</span> locale ou territoriale des intervenants</td></tr>\n        <tr><td><span class=\"kw-def\">USP</span> — Unité de soins palliatifs</td><td>Unité hospitalière à activité <span class=\"kw-alerte\">spécifique et exclusive</span> en soins palliatifs ; triple mission soins / formation / recherche ; accueille <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">situations complexes</span></td></tr>\n        <tr><td><span class=\"kw-def\">HAD</span> — <span class=\"kw-alerte\">Hospitalisation</span> à domicile</td><td>Prise en charge médicale et infirmière soutenue au domicile ou en médico-social ; alternative à l'<span class=\"kw-alerte\">hospitalisation</span></td></tr>\n      </tbody>\n    </table>\n    <p>À l'<strong>hôpital</strong>, la prise en charge est organisée en <span class=\"kw-def\">3 niveaux</span> (circulaire de 2008) :</p>\n    <table class=\"descriptif-table\">\n      <thead><tr><th>Niveau</th><th>Structure</th><th>Rôle</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-def\">Niveau 1</span></td><td>Service hospitalier <strong>sans</strong> LISP</td><td>Prise en charge des <span class=\"kw-clinique\">situations simples</span>, avec soutien éventuel de l'EMSP</td></tr>\n        <tr><td><span class=\"kw-def\">Niveau 2</span></td><td>Service hospitalier <strong>avec</strong> LISP</td><td>Lits dédiés ; service confronté à des fins de vie / décès fréquents</td></tr>\n        <tr><td><span class=\"kw-def\">Niveau 3</span></td><td>USP</td><td>Situations <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">plus complexes</span></td></tr>\n        <tr><td>Transversal</td><td>EMSP</td><td>Soutien des niveaux 1 et 2, en intra comme en extra-hospitalier</td></tr>\n      </tbody>\n    </table>\n    <p>En <strong>ambulatoire</strong>, l'organisation est également graduée : <span class=\"kw-clinique\">soins primaires</span> (médecin traitant, infirmier libéral, autres professionnels) au niveau de base ; <span class=\"kw-def\">HAD</span> et établissements médico-sociaux au niveau intermédiaire ; <span class=\"kw-def\">EMSP extra-hospitalière / Réseau</span> au niveau de l'expertise et de la coordination.</p>\n    <div class=\"obj-callout info\"><strong>Repère épidémiologique.</strong> Environ <span class=\"kw-chiffre\">80 %</span> des patients souhaitent finir leur vie à domicile, alors que <span class=\"kw-chiffre\">25 %</span> seulement y décèdent (chiffres 2017).</div>","frequence":1,"liens":[{"href":"https://www.sfap.org/rubrique/pallia-10","label":"sfap.org"}]},{"id":"139-3","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir identifier une situation relevant de soins palliatifs","contenu":"<p>Une <span class=\"kw-def\">situation relevant de soins palliatifs</span> correspond au <span class=\"kw-alerte\">caractère non guérissable</span> d'une <span class=\"kw-clinique\">maladie grave, chronique, évolutive et potentiellement létale</span>. L'identifier permet d'engager une <span class=\"kw-ttt\">démarche palliative</span> et de décider, si besoin, du recours à une équipe spécialisée.</p>\n    <p>Le <span class=\"kw-def\">score PALLIA-10</span> est l'outil de repérage de référence. Une <strong>réponse positive à l'item 1</strong> est nécessaire pour pouvoir utiliser le <span class=\"kw-def\">score</span> ; <span class=\"kw-chiffre\">plus de 3 réponses positives</span> font envisager le recours à une équipe de soins palliatifs.</p>\n    <table class=\"descriptif-table\">\n      <thead><tr><th>N°</th><th>Critère PALLIA-10</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-chiffre\">1</span></td><td>Patient atteint d'une <span class=\"kw-alerte\">maladie qui ne guérira pas</span> — <strong>réponse positive indispensable</strong> pour utiliser le <span class=\"kw-def\">score</span></td></tr>\n        <tr><td><span class=\"kw-chiffre\">2</span></td><td>Présence de <span class=\"kw-clinique\">facteurs pronostiques péjoratifs</span> — validés en oncologie : <span class=\"kw-bio\">hypoalbuminémie</span>, <span class=\"kw-bio\">syndrome inflammatoire biologique</span>, <span class=\"kw-bio\">lymphopénie</span>, indice de performance altéré</td></tr>\n        <tr><td><span class=\"kw-chiffre\">3</span></td><td>Maladie <span class=\"kw-clinique\">rapidement évolutive</span></td></tr>\n        <tr><td><span class=\"kw-chiffre\">4</span></td><td>Patient ou entourage <span class=\"kw-clinique\">demandeurs</span> d'une prise en charge palliative</td></tr>\n        <tr><td><span class=\"kw-chiffre\">5</span></td><td><span class=\"kw-alerte\">Symptômes non soulagés</span> malgré <span class=\"kw-clinique\">les</span> traitements (douleurs, <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">vomissements</span>...)</td></tr>\n        <tr><td><span class=\"kw-chiffre\">6</span></td><td>Facteurs de <span class=\"kw-clinique\">vulnérabilité psychique</span> du patient ou de l'entourage (tristesse, angoisse, repli, agressivité, troubles du comportement)</td></tr>\n        <tr><td><span class=\"kw-chiffre\">7</span></td><td>Facteurs de <span class=\"kw-clinique\">vulnérabilité sociale</span> (<span class=\"kw-def\">isolement</span>, précarité, dépendance financière, personne dépendante à charge)</td></tr>\n        <tr><td><span class=\"kw-chiffre\">8</span></td><td>Difficultés d'<span class=\"kw-clinique\">intégration des informations</span> sur la maladie ou le <span class=\"kw-def\">pronostic</span> (mécanismes de défense rendant la communication difficile)</td></tr>\n        <tr><td><span class=\"kw-chiffre\">9</span></td><td>Questionnements ou divergences au sein de l'équipe sur la <span class=\"kw-clinique\">cohérence du projet de soins</span> (prescriptions anticipées, indications d'hydratation, d'alimentation, d'<span class=\"kw-ttt\">antibiothérapie</span>, de SNG, de transfusion, statut réanimatoire)</td></tr>\n        <tr><td><span class=\"kw-chiffre\">10</span></td><td>Questionnements sur l'attitude à adopter face à un <span class=\"kw-clinique\">refus de traitement</span>, une limitation ou un arrêt de traitement, un conflit de valeurs</td></tr>\n      </tbody>\n    </table>\n    <p>Le <span class=\"kw-def\">PALLIA-10 géronto</span> est une version adaptée à la personne âgée. <span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">trajectoires de fin de vie</span> aident également à reconnaître une situation palliative et à en anticiper l'<span class=\"kw-clinique\">évolution</span> (déclin rapide, déclin graduel, déclin lent — voir l'objectif sur les spécificités selon la pathologie).</p>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 140 — Soins palliatifs 2 - accompagnement de la personne et de son entourage · 141 — Soins palliatifs 3 - sédation - fin de vie</em></p>","frequence":1},{"id":"139-4","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir identifier et évaluer les symptômes les plus fréquemment rencontrés en phase palliative ou terminale des maladies graves, chroniques ou létales : respiratoires, digestifs, neurologiques, psychiatriques, ORL","contenu":"<p>La phase palliative ou terminale s'accompagne de symptômes multiples qu'il faut savoir <span class=\"kw-clinique\">identifier</span> puis <span class=\"kw-clinique\">évaluer</span> (intensité, retentissement, auto-évaluation) avant tout traitement.</p>\n    <table class=\"descriptif-table\">\n      <thead><tr><th>Appareil</th><th>Symptômes &amp; repères d'identification / évaluation</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-def\">Respiratoire</span></td><td>\n          <strong><span class=\"kw-clinique\">Dyspnée</span> :</strong> expérience <span class=\"kw-clinique\">subjective</span> d'inconfort respiratoire (« soif d'<span class=\"kw-def\">air</span> »), ± <span class=\"kw-clinique\">polypnée</span>, ± <span class=\"kw-alerte\">détresse</span>, souvent associée à l'<span class=\"kw-clinique\">anxiété</span> ; évaluation = <span class=\"kw-clinique\">fréquence respiratoire</span>, <span class=\"kw-clinique\">cyanose</span>, signes de lutte, <span class=\"kw-clinique\">auto-évaluation par EVA</span>, retentissement (NYHA, MRC) — la <span class=\"kw-alerte\">SaO2 n'est PAS corrélée à l'inconfort</span> et ne sert pas de mesure d'évaluation ;<br>\n          <strong><span class=\"kw-clinique\">Râles</span> agoniques :</strong> bruits expiratoires humides des derniers jours de vie\n        </td></tr>\n        <tr><td><span class=\"kw-def\">Digestif</span></td><td>\n          <strong><span class=\"kw-clinique\">Nausées</span> / vomissements :</strong> préciser le mécanisme (<span class=\"kw-etio\">médicamenteux</span>, métabolique, occlusif, central, vestibulaire) ;<br>\n          <strong>Syndrome occlusif :</strong> <span class=\"kw-clinique\">vomissements de stase</span>, coliques et douleurs abdominales, arrêt des gaz et des selles &gt; <span class=\"kw-chiffre\">3 jours</span>, météorisme ;<br>\n          <strong><span class=\"kw-clinique\">Constipation</span> :</strong> &lt; <span class=\"kw-chiffre\">3 selles spontanées / semaine</span> + au moins un signe (exonération incomplète, difficultés d'évacuation, selles grumeleuses) ;<br>\n          <strong>Fausses routes :</strong> <span class=\"kw-clinique\">toux perprandiale</span>, voix « mouillée » / gargouillante après déglutition (stase laryngée)\n        </td></tr>\n        <tr><td><span class=\"kw-def\">Neuro-psychique</span></td><td>\n          <strong>Confusion :</strong> <span class=\"kw-chiffre\">85 %</span> des patients dans <span class=\"kw-clinique\">les</span> dernières semaines ; triade = trouble de l'<span class=\"kw-clinique\">état de conscience</span> + fluctuations <span class=\"kw-clinique\">cognitives</span> + <span class=\"kw-clinique\">troubles de la perception</span> (hallucinations visuelles) ; forme agitée ou ralentie ;<br>\n          <strong>Anxiété :</strong> manifestations <span class=\"kw-clinique\">psychiques</span> (hypervigilance, irritabilité, troubles du sommeil) et <span class=\"kw-clinique\">somatiques</span> (oppression thoracique, <span class=\"kw-clinique\">palpitations</span>, tremblements) ; évaluation par échelle <span class=\"kw-clinique\">HAD</span>\n        </td></tr>\n        <tr><td><span class=\"kw-def\">ORL / sphère buccale</span></td><td>Identifier le type de bouche : <strong>normale</strong> ; <strong>sèche</strong> (<span class=\"kw-etio\">iatrogène</span> fréquente) ; <strong><span class=\"kw-etio\">mycosique</span></strong> (langue rouge framboisée, dépapillée, goût métallique) ; <strong>douloureuse</strong> ; <strong><span class=\"kw-etio\">hémorragique</span></strong></td></tr>\n      </tbody>\n    </table>\n    <div class=\"obj-callout info\"><strong>Piège classique.</strong> La <span class=\"kw-alerte\">saturation en oxygène n'évalue pas la dyspnée</span> : l'inconfort respiratoire est une donnée subjective, à recueillir par auto-évaluation.</div>","frequence":2},{"id":"139-5","rang":"A","rubrique":"Prise en charge","titre":"Savoir faire appel à des équipes ressources ou à des services de recours","contenu":"<p>Faire appel à une <span class=\"kw-def\">équipe ressource</span> ou à un <span class=\"kw-def\">service de recours</span> apporte une expertise lorsque la situation dépasse <span class=\"kw-clinique\">les</span> compétences ou les moyens de l'équipe en place.</p>\n    <p>Le <span class=\"kw-def\">score PALLIA-10</span> aide à décider du recours : une réponse positive à l'item 1 est nécessaire pour utiliser le <span class=\"kw-def\">score</span> ; <span class=\"kw-chiffre\">plus de 3 réponses positives</span> font envisager le recours à une équipe de soins palliatifs.</p>\n    <table class=\"descriptif-table\">\n      <thead><tr><th>Structure ressource</th><th>Quand y faire appel ?</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-def\">EMSP intra-hospitalière</span></td><td>Demande émanant d'un <span class=\"kw-clinique\">professionnel de santé</span> (pouvant être initiée par le patient ou <span class=\"kw-clinique\">les</span> proches), transmise après concertation avec le cadre de santé et le médecin en charge ; intervient en <strong>soutien des niveaux 1 et 2</strong></td></tr>\n        <tr><td><span class=\"kw-def\">LISP</span></td><td>Situation palliative <span class=\"kw-clinique\">non complexe</span> ; admission sur <span class=\"kw-clinique\">évaluation globale médico-psychosociale</span>, avec l'avis du patient ou des proches, du médecin habituel et du médecin référent du service</td></tr>\n        <tr><td><span class=\"kw-def\">USP</span></td><td><span class=\"kw-alerte\">Situations complexes</span> : charge en soins trop lourde, technicité ou plateau technique nécessaire, questionnements éthiques, souffrances morales et socio-familiales complexes, séjour de répit pour soutenir l'aidant</td></tr>\n        <tr><td><span class=\"kw-def\">HAD</span></td><td>Besoin d'une prise en charge médicale et infirmière soutenue à domicile ou en EHPAD ; le <span class=\"kw-clinique\">médecin traitant reste responsable médical</span></td></tr>\n        <tr><td><span class=\"kw-def\">EMSP extra-hospitalière / Réseau</span></td><td>Appui spécialisé à domicile ou en médico-social ; sollicité sous couvert d'une <span class=\"kw-clinique\">signature de convention</span> ; indispensable dans <span class=\"kw-clinique\">les</span> situations complexes</td></tr>\n      </tbody>\n    </table>\n    <p>Quel que soit le lieu, des <strong>bénévoles d'accompagnement</strong> (associations dédiées) peuvent intervenir selon <span class=\"kw-clinique\">les</span> souhaits du patient. La <span class=\"kw-clinique\">coordination</span> repose sur un professionnel <span class=\"kw-ttt\">référent</span> et un <span class=\"kw-ttt\">cahier de liaison</span> ; l'anticipation des situations de <span class=\"kw-alerte\">détresse</span> passe par des <span class=\"kw-ttt\">prescriptions anticipées personnalisées</span> et la transmission d'une <span class=\"kw-ttt\">fiche de liaison</span> aux services d'<span class=\"kw-alerte\">urgence</span> (15 / <span class=\"kw-alerte\">SAMU</span>).</p>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 143 — Soins palliatifs en <span class=\"kw-alerte\">réanimation</span> · 142 — Soins palliatifs en pédiatrie</em></p>","frequence":2},{"id":"139-6","rang":"B","rubrique":"Prise en charge","titre":"Connaître les étapes d’une démarche de soins du patient et de son entourage lors des situations les plus fréquemment rencontrées en phase palliative ou terminale des maladies graves, chroniques ou létales","contenu":"<p>La <span class=\"kw-def\">démarche de soins</span> en situation palliative est une prise en charge <span class=\"kw-ttt\">globale, continue et pluridisciplinaire</span>, centrée sur le patient et son entourage. Elle se déroule en étapes :</p>\n    <ul>\n      <li><strong>Évaluation globale</strong> — bilan <span class=\"kw-clinique\">médico-psycho-social</span> du patient, repérage de l'<span class=\"kw-clinique\">aidant principal</span> et de la <span class=\"kw-clinique\">personne de confiance</span> si elle a été désignée.</li>\n      <li><strong>Projet de soins personnalisé</strong> — objectifs hiérarchisés avec le patient ; rédaction éventuelle de <span class=\"kw-clinique\">directives anticipées</span>.</li>\n      <li><strong>Coordination pluridisciplinaire</strong> — un professionnel <span class=\"kw-ttt\">référent</span> identifié, partage d'informations via un <span class=\"kw-ttt\">cahier de liaison</span>.</li>\n      <li><strong>Anticipation</strong> — <span class=\"kw-ttt\">prescriptions anticipées personnalisées</span> disponibles, <span class=\"kw-ttt\">fiche de liaison</span> transmise aux services d'<span class=\"kw-alerte\">urgence</span> (15 / <span class=\"kw-alerte\">SAMU</span>), identification des risques prévisibles.</li>\n      <li><strong><span class=\"kw-def\">Réévaluation</span> continue</strong> — adaptation des soins, évaluation de l'état du patient et de l'<span class=\"kw-clinique\">épuisement des aidants</span>.</li>\n      <li><strong>Soutien de l'entourage</strong> — écoute et accompagnement des proches, <span class=\"kw-chiffre\">avant, pendant et après le décès</span>.</li>\n    </ul>\n    <p>Exemple concret — <strong>organisation de la sortie de l'hôpital</strong> lorsqu'un patient peut et souhaite rentrer dans son lieu de vie : information du patient et de l'entourage (avec son accord), accord et disponibilité des <span class=\"kw-clinique\">professionnels de soins primaires</span> (médecin traitant), évaluation de l'environnement soignant à domicile, identification des risques prévisibles et du type de recours en cas de <span class=\"kw-alerte\">détresse</span>, vérification systématique d'une <span class=\"kw-ttt\">check-list de sortie</span> le jour de la sortie.</p>","frequence":0},{"id":"139-7","rang":"B","rubrique":"Prise en charge","titre":"Connaître les étapes d’une démarche de traitement du patient et de son entourage lors des situations les plus fréquemment rencontrées en phase palliative ou terminale des maladies graves, chroniques ou létales","contenu":"<p>La <span class=\"kw-def\">démarche de traitement</span> d'un symptôme en phase palliative suit une logique constante en trois temps :</p>\n    <table class=\"descriptif-table\">\n      <thead><tr><th>Temps</th><th>Contenu</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-def\">1. Démarche évaluative</span></td><td>Identifier et <span class=\"kw-clinique\">évaluer le symptôme</span> ainsi que son retentissement : intensité, signes physiques et fonctionnels, auto-évaluation</td></tr>\n        <tr><td><span class=\"kw-def\">2. Démarche étiologique raisonnée</span></td><td><span class=\"kw-clinique\">Anamnèse</span>, revue des <span class=\"kw-ttt\">traitements</span> en cours, examen <span class=\"kw-clinique\">clinique</span> et bilan <span class=\"kw-bio\">paraclinique</span> ciblé (ex. <span class=\"kw-imagerie\">radiographie</span> thoracique, <span class=\"kw-bio\">hémoglobine</span>)</td></tr>\n        <tr><td><span class=\"kw-def\">3. Prise en charge</span></td><td>Si une <strong>étiologie curable</strong> est retrouvée : <span class=\"kw-ttt\">traitement étiologique</span>, en y associant d'emblée des mesures symptomatiques ; sinon : <span class=\"kw-ttt\">traitement symptomatique</span> d'emblée</td></tr>\n      </tbody>\n    </table>\n    <p>Principes transversaux du traitement :</p>\n    <ul>\n      <li>Le traitement symptomatique <strong>ne dispense jamais</strong> de rechercher une <span class=\"kw-clinique\">cause curable</span>.</li>\n      <li><span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">traitements médicamenteux</span> ne sont <strong>pas systématiques</strong> : ils sont décidés après <span class=\"kw-clinique\">délibération préalable</span> et font l'objet d'une <span class=\"kw-clinique\">évaluation régulière</span>.</li>\n      <li><span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">mesures non médicamenteuses</span> accompagnent toujours les mesures médicamenteuses.</li>\n      <li>Toute décision s'inscrit dans une réflexion sur la <span class=\"kw-alerte\">proportionnalité</span> des invest<span class=\"kw-chiffre\">iga</span>tions et des traitements.</li>\n    </ul>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 140 — Soins palliatifs 2 - accompagnement de la personne et de son entourage</em></p>","frequence":1},{"id":"139-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les étapes d’une démarche d’accompagnement du patient et de son entourage lors des situations les plus fréquemment rencontrées en phase palliative ou terminale des maladies graves chroniques ou létales,","contenu":"<p>L'<span class=\"kw-def\">accompagnement</span> est une dimension constitutive de la démarche palliative : il s'adresse au <span class=\"kw-clinique\">patient</span> comme à son <span class=\"kw-clinique\">entourage</span>. <span class=\"kw-clinique\">Les</span> fiches d'organisation de l'item 139 en donnent les repères suivants :</p>\n    <ul>\n      <li><strong>Écoute et accompagnement des proches</strong> — mission de l'ensemble des professionnels du service, notamment dans <span class=\"kw-clinique\">les</span> LISP.</li>\n      <li><strong>Soutien des proches</strong> <span class=\"kw-chiffre\">avant, pendant et après le décès</span> : respect des rites mortuaires, aide aux démarches administratives.</li>\n      <li><strong>Bénévoles d'accompagnement</strong> — <span class=\"kw-clinique\">les</span> associations qui les forment et les encadrent peuvent intervenir auprès du patient selon ses souhaits et ses besoins, quel que soit son lieu de vie.</li>\n      <li><strong>Prise en charge de l'entourage</strong> — information, explication, soutien psychologique ; évaluation continue de l'<span class=\"kw-clinique\">épuisement et du stress des aidants</span>.</li>\n    </ul>\n    <div class=\"obj-callout warning\"><strong>À compléter.</strong> <span class=\"kw-clinique\">Les</span> étapes détaillées de la <em>démarche d'accompagnement</em> (communication, repères relationnels et repères éthiques) ne sont pas développées dans les fiches sources de l'item 139 : elles relèvent de l'item 140. Kevin enrichira si besoin (Collège SFAP).</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 140 — Soins palliatifs 2 - accompagnement de la personne et de son entourage</em></p>","frequence":0},{"id":"139-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les traitements des symptômes les plus fréquemment rencontrés en phase palliative des maladies graves, chroniques ou létales : respiratoires, digestifs, neurologiques, psychiatriques, ORL","contenu":"<p>Une fois le symptôme identifié et la cause recherchée, le traitement associe des mesures <span class=\"kw-ttt\">étiologiques</span>, <span class=\"kw-ttt\">symptomatiques</span> et <span class=\"kw-ttt\">non médicamenteuses</span>.</p>\n    <p><strong>Symptômes respiratoires</strong></p>\n    <table class=\"descriptif-table\">\n      <thead><tr><th>Symptôme</th><th>Traitement</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-clinique\">Dyspnée</span></td><td>\n          <strong>Étiologique :</strong> bronchodilatateur (BPCO), <span class=\"kw-ttt\">corticoïdes</span> ou chimiothérapie (lymphangite carcinomateuse), <span class=\"kw-ttt\">diurétique</span> (<span class=\"kw-ci\">insuffisance cardiaque</span>), <span class=\"kw-ttt\">ponction</span> évacuatrice (pleurésie) ;<br>\n          <strong><span class=\"kw-ttt\">Morphine</span> :</strong> <span class=\"kw-ttt\">opioïde</span> de référence — diminue la sensation de <span class=\"kw-clinique\">dyspnée</span> (action sur <span class=\"kw-clinique\">les</span> centres respiratoires, abaisse le seuil de réponse à l'hypercapnie, effet bradypnéisant et anxiolytique), utile <span class=\"kw-chiffre\">même en l'absence de douleur</span> et chez le patient naïf de morphine ;<br>\n          <strong>Benzodiazépine :</strong> <span class=\"kw-ttt\">alprazolam</span> ou <span class=\"kw-ttt\">oxazépam</span> per os, <span class=\"kw-ttt\">midazolam</span> parentéral — pour l'anxiété associée, objectif d'anxiolyse sans sédation ;<br>\n          <strong><span class=\"kw-ttt\">Oxygénothérapie</span> :</strong> <span class=\"kw-alerte\">non systématique</span>, à discuter en phase terminale selon le bénéfice ressenti, <strong>sans objectif de saturation</strong> ;<br>\n          <strong>Non <span class=\"kw-etio\">médicamenteux</span> :</strong> installation demi-assise, ambiance calme, atmosphère aérée, soins de bouche fréquents\n        </td></tr>\n        <tr><td><span class=\"kw-clinique\">Râles agoniques</span></td><td><span class=\"kw-ttt\">Scopolamine</span> (anticholinergique, SC / IV ou patch) ; diminution voire arrêt des apports hydriques ; position demi-assise ou semi-latérale ; soins de bouche — <span class=\"kw-ci\">aspirations trachéo-bronchiques à proscrire</span> (agressives en toute fin de vie)</td></tr>\n      </tbody>\n    </table>\n    <p><strong>Symptômes digestifs</strong></p>\n    <table class=\"descriptif-table\">\n      <thead><tr><th>Symptôme</th><th>Traitement</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-clinique\">Nausées / vomissements</span></td><td>Traitement étiologique ++ ; antiémétique adapté au mécanisme : <span class=\"kw-ttt\">neuroleptiques</span> (métoclopramide, métopimazine, halopéridol), <span class=\"kw-ttt\">sétrons</span>, <span class=\"kw-ttt\">corticoïdes</span>, <span class=\"kw-ttt\">scopolamine</span>, antihistaminiques ; mesures non médicamenteuses (alimentation fractionnée, froide, légère, sans odeurs)</td></tr>\n        <tr><td><span class=\"kw-clinique\">Occlusion sur carcinose</span></td><td>\n          <strong><span class=\"kw-chiffre\">J1</span> à J3 :</strong> patient à jeun + réhydratation IV ou SC, SNG non systématique ; <span class=\"kw-ttt\">antalgique</span>, neuroleptique injectable, <span class=\"kw-ttt\">IPP</span>, <span class=\"kw-ttt\">butylbromure de scopolamine</span>, <span class=\"kw-ttt\">corticoïdes</span> en cure courte — <span class=\"kw-ci\">métoclopramide contre-indiqué</span> (action prokinétique, risque d'inhalation) ;<br>\n          <strong>J4 :</strong> en l'absence de levée → analogue de la <span class=\"kw-ttt\">somatostatine</span> ;<br>\n          <strong><span class=\"kw-chiffre\">J7</span> :</strong> si <span class=\"kw-clinique\">vomissements</span> réfractaires ou SNG &gt; <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> L/24</span> h → discuter une gastrostomie de décharge\n        </td></tr>\n        <tr><td><span class=\"kw-clinique\">Constipation</span></td><td><span class=\"kw-ttt\">Laxatif systématique</span> associé à toute prescription d'<span class=\"kw-ttt\">opioïde fort</span> (osmotique type macrogol, ou stimulant type bisacodyl) + <span class=\"kw-ttt\">règles hygiéno-diététiques</span> ; curatif après <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> jours</span> sans selle : bithérapie laxative, puis <span class=\"kw-ttt\">antagoniste morphinique périphérique</span> (méthylnaltrexone) — <span class=\"kw-ci\">contre-indiqué en cas d'occlusion</span></td></tr>\n        <tr><td><span class=\"kw-clinique\">Soins de bouche</span></td><td>Base : bains de bouche au <span class=\"kw-bio\">bicarbonate</span> de sodium après <span class=\"kw-clinique\">les</span> repas ; bouche sèche → <span class=\"kw-ttt\">salive artificielle</span>, humidification ; <span class=\"kw-etio\">mycosique</span> → <span class=\"kw-ttt\">antifongique</span> (<span class=\"kw-ttt\">amphotéricine B</span>) ; douloureuse → <span class=\"kw-ttt\">antalgique</span> local (lidocaïne), bain de bouche <span class=\"kw-ttt\">aspirine</span> ou <span class=\"kw-ttt\">sucralfate</span> ; <span class=\"kw-etio\">hémorragique</span> → lidocaïne adrénalinée, acide tranexamique</td></tr>\n      </tbody>\n    </table>\n    <p><strong>Symptômes neuro-psychiques</strong></p>\n    <table class=\"descriptif-table\">\n      <thead><tr><th>Symptôme</th><th>Traitement</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-clinique\">Confusion</span></td><td>Traitement <span class=\"kw-ttt\">étiologique = priorité</span> ; mesures générales : supprimer <span class=\"kw-clinique\">les</span> traitements non indispensables, diminuer les <span class=\"kw-ttt\">corticoïdes</span>, maintenir l'hydratation et la nutrition, environnement calme avec repères ; <span class=\"kw-ci\">éviter les contentions physiques</span> ; recours <span class=\"kw-etio\">médicamenteux</span> rare — <span class=\"kw-ttt\">neuroleptique</span> à faible dose si agitation ou hallucinations compromettant la sécurité</td></tr>\n        <tr><td><span class=\"kw-clinique\">Anxiété</span></td><td>Mesures non médicamenteuses d'abord (soutien, relaxation, thérapies occupationnelles) ; <span class=\"kw-ttt\">benzodiazépine</span> à demi-vie courte et faible dose ; <span class=\"kw-ttt\">neuroleptique</span> en cas d'échec ou de <span class=\"kw-ci\">contre-indication</span> ; <span class=\"kw-ttt\">ISRS</span> (surveiller le syndrome sérotoninergique)</td></tr>\n      </tbody>\n    </table>\n    <p><strong>Autres symptômes</strong> — <span class=\"kw-clinique\">asthénie</span> : traiter la cause, <span class=\"kw-ttt\">corticothérapie</span>, <span class=\"kw-ttt\">activité physique adaptée</span> (<span class=\"kw-alerte\">aucun médicament n'a l'AMM</span> dans cette indication) ; <span class=\"kw-clinique\">syndrome anorexie-cachexie</span> : aucun traitement curatif, soutien psychologique, <span class=\"kw-ttt\">corticoïdes</span> (améliorent l'<span class=\"kw-clinique\">anorexie</span> sans impact sur la cachexie), le support nutritionnel artificiel est <span class=\"kw-alerte\">illusoire voire délétère</span>.</p>\n    <div class=\"obj-callout info\"><strong>Symptôme réfractaire.</strong> Lorsqu'un symptôme reste réfractaire malgré un traitement bien conduit, une sédation peut être discutée — cette démarche relève de l'item 141 et n'est pas développée ici.</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 141 — Soins palliatifs 3 - sédation - fin de vie</em></p>","frequence":3},{"id":"139-10","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir identifier les caractéristiques cliniques de la phase agonique des maladies graves, chroniques, évolutives ou létales","contenu":"<p>La <span class=\"kw-def\">phase agonique</span> est la <strong>dernière des phases palliatives</strong>. Elle succède à la <span class=\"kw-def\">phase terminale</span> (marquée par un <span class=\"kw-alerte\">déclin fonctionnel et une dégradation clinique irréversibles</span>) et précède immédiatement le décès.</p>\n    <p>Elle se caractérise par :</p>\n    <ul>\n      <li>un <span class=\"kw-alerte\">décès imminent</span> ;</li>\n      <li>une <span class=\"kw-alerte\">défaillance multiviscérale évolutive et irréversible</span>.</li>\n    </ul>\n    <p>Deux repères cliniques fréquents de cette période, documentés dans <span class=\"kw-clinique\">les</span> fiches sources de l'item 139 :</p>\n    <table class=\"descriptif-table\">\n      <thead><tr><th>Signe</th><th>Caractéristiques</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-clinique\">Râles agoniques</span></td><td>Bruits expiratoires humides liés au passage de l'<span class=\"kw-def\">air</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">sécrétions accumulées</span> (salivaires et bronchiques) dans le pharynx et la trachée ; présents dans les <span class=\"kw-chiffre\">derniers jours / dernières heures</span> de vie chez <span class=\"kw-chiffre\">&gt; 50 %</span> des patients ayant perdu les <span class=\"kw-clinique\">réflexes de toux et de déglutition</span></td></tr>\n        <tr><td><span class=\"kw-clinique\">Syndrome confusionnel</span></td><td>Présent chez <span class=\"kw-chiffre\">85 %</span> des patients dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">dernières semaines</span> de vie ; constitue un <span class=\"kw-alerte\">facteur de gravité pronostique</span></td></tr>\n      </tbody>\n    </table>\n    <div class=\"obj-callout warning\"><strong>À compléter.</strong> La sémiologie clinique détaillée de la phase agonique (autres signes neurologiques, cutanés, respiratoires et hémodynamiques) n'est pas développée dans <span class=\"kw-clinique\">les</span> fiches sources 139 du dossier. Kevin enrichira (Collège SFAP, recos HAS).</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 141 — Soins palliatifs 3 - sédation - fin de vie · 140 — Soins palliatifs 2 - accompagnement de la personne et de son entourage</em></p>","frequence":2},{"id":"139-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître les spécificités des soins palliatifs auprès de malades atteints de pathologies oncologiques et hématologiques malignes, de maladies neurologiques dégénératives, d’insuffisances d’organe terminales","contenu":"<p>L'<span class=\"kw-clinique\">évolution</span> d'une maladie grave vers le décès suit des <span class=\"kw-def\">trajectoires de fin de vie</span> différentes selon le type de pathologie. Trois trajectoires sont décrites :</p>\n    <table class=\"descriptif-table\">\n      <thead><tr><th>Trajectoire</th><th>Profil évolutif</th><th>Pathologies</th></tr></thead>\n      <tbody>\n        <tr><td><span class=\"kw-def\">1 — Déclin rapide</span> (<span class=\"kw-chiffre\">≈ 50 %</span>)</td><td><span class=\"kw-clinique\">Évolution</span> progressive, avec une <span class=\"kw-clinique\">phase terminale relativement bien définie</span></td><td>Pathologies <span class=\"kw-clinique\">oncologiques</span> et hématologiques malignes</td></tr>\n        <tr><td><span class=\"kw-def\">2 — Déclin graduel</span> (<span class=\"kw-chiffre\">≈ 40 %</span>)</td><td>Épisodes de <span class=\"kw-alerte\">détérioration aiguë</span> entrecoupés de phases de récupération ; <span class=\"kw-alerte\">mort soudaine et inattendue</span> possible</td><td><span class=\"kw-clinique\">Insuffisances d'organe terminales</span> (cardiaque, respiratoire, rénale, hépatique)</td></tr>\n        <tr><td><span class=\"kw-def\">3 — Déclin lent</span></td><td><span class=\"kw-clinique\">Perte très progressive</span> des capacités fonctionnelles et cognitives</td><td>Maladies <span class=\"kw-clinique\">neurologiques dégénératives</span></td></tr>\n      </tbody>\n    </table>\n    <div class=\"obj-callout info\"><strong>Intérêt pratique.</strong> Reconnaître la trajectoire aide à <span class=\"kw-clinique\">anticiper</span> l'<span class=\"kw-clinique\">évolution</span>, à adapter le <span class=\"kw-ttt\">projet de soins</span> et à informer le patient et ses proches. La trajectoire 2 expose au risque de décès lors d'un épisode aigu : d'où l'intérêt majeur des <span class=\"kw-ttt\">prescriptions anticipées personnalisées</span>.</div>\n    <p class=\"obj-renvois\"><em>📎 Items liés : 143 — Soins palliatifs en <span class=\"kw-alerte\">réanimation</span> · 142 — Soins palliatifs en pédiatrie</em></p>","frequence":1}],"astuces":[],"liensGlobaux":[{"href":"https://sfap.org/system/files/echelle_de_vigilance_-_agitation_de_richmond.pdf","label":"sfap.org"}],"cards":[]};